    base: str
    index: int | str


@dataclass(frozen=True, slots=True)
class BinaryTerm:
    op: str
    left: Term
    right: Term


@dataclass(frozen=True, slots=True)
class FuncCall:
    name: str
    args: tuple[Term, ...]


Term = Constant | SymbolRef | IndexedRef | BinaryTerm | FuncCall


